function lengthOfLongestSubstring(s) {
  let best = 0;
  for (let i = 0; i < s.length; i++) { const seen = new Set(); let j = i; while (j < s.length && !seen.has(s[j])) seen.add(s[j++]); best = Math.max(best, j - i); }
  return best;
}
